"""In-memory queue used by the notification worker."""
class JobQueue:
    def __init__(self):
        self.pending = {}

    def enqueue(self, key, payload, due):
        self.pending[key] = {"key": key, "payload": payload, "due": due}

    def drain(self, now, handler):
        delivered = 0
        for key, job in list(self.pending.items()):
            if job["due"] > now:
                continue
            handler(job["payload"])
            # A successful handler may have replaced this job with a successor.
            if self.pending.get(key) is job:
                del self.pending[key]
            delivered += 1
        return delivered

