const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const root = path.resolve(__dirname, '..');
const original = fs.readFileSync(path.join(root, '.verification/original-index.cjs'), 'utf8');
const directory = fs.mkdtempSync(path.join(root, '.verification/mutants-'));
try {
  for (const [name, source] of [
    ['currency', original.replace("'CNY '", "'¥'")],
    ['cancelled-delivery', original.replace('if (listeners.has(fn)) fn(value)', 'fn(value)')],
    ['validation-order', original.replace(
      "  if (!Array.isArray(lines)) throw new TypeError('lines');\n  if (!Number.isFinite(rate) || rate < 0) throw new RangeError('rate');",
      "  if (!Number.isFinite(rate) || rate < 0) throw new RangeError('rate');\n  if (!Array.isArray(lines)) throw new TypeError('lines');")]
  ]) {
    assert.notEqual(source, original);
    const mutant = path.join(directory, name + '.cjs');
    fs.writeFileSync(mutant, source);
    const result = spawnSync(process.execPath,
      [path.join(__dirname, 'compatibility.cjs'), mutant], { encoding: 'utf8' });
    assert.equal(result.status, 1, result.stderr);
    assert.match(result.stderr, /AssertionError/);
    console.log('PASS sensitivity: rejects ' + name);
  }
} finally {
  fs.rmSync(directory, { recursive: true, force: true });
}

