'use strict';
const assert = require('node:assert/strict');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const turn = () => new Promise(resolve => setImmediate(resolve));
function errorOf(fn) {
  try { fn(); } catch (error) { return [error.name, error.message]; }
  assert.fail('Expected an error');
}

async function observe(entry) {
  const api = require(entry);
  const { makeInvoice, createFeed } = api;
  assert.deepEqual(Object.keys(api), ['makeInvoice', 'createFeed']);
  assert.equal(makeInvoice.length, 2);
  assert.equal(createFeed.length, 0);
  const errors = [
    errorOf(() => makeInvoice(null, -1)),
    ...[-1, NaN, Infinity, '0'].map(rate => errorOf(() => makeInvoice([], rate))),
    ...[
      { priceCents: -1, quantity: 1 },
      { priceCents: 1.5, quantity: 1 },
      { priceCents: 1, quantity: -1 },
      { priceCents: 1, quantity: Number.MAX_SAFE_INTEGER + 1 }
    ].map(line => errorOf(() => makeInvoice([line], 0)))
  ];
  assert.deepEqual(errors, [['TypeError', 'lines'],
    ...Array(4).fill(['RangeError', 'rate']), ...Array(4).fill(['RangeError', 'line'])]);
  let invalidRecordCalls = 0;
  assert.throws(() => makeInvoice([{ priceCents: 1, quantity: -1 }], 0,
    () => invalidRecordCalls++), RangeError);
  assert.equal(invalidRecordCalls, 0);
  const records = [];
  const invoice = makeInvoice([{ priceCents: 1, quantity: 1 },
    { priceCents: 1, quantity: 1 }], 0.25, (...args) => records.push(args));
  assert.deepEqual(invoice, { totalCents: 3, label: 'CNY 0.03' });
  assert.deepEqual(records, [['CNY 0.03', 3]]);
  assert.ok(Object.isFrozen(invoice));
  assert.throws(() => { invoice.totalCents = 4; }, TypeError);
  const empty = makeInvoice([], 0);
  assert.deepEqual(empty, { totalCents: 0, label: 'CNY 0.00' });
  const marker = new Error('record failed');
  let recordCalls = 0;
  assert.throws(() => makeInvoice([], 0, () => { recordCalls++; throw marker; }),
    error => error === marker);
  assert.equal(recordCalls, 1);

  const seen = [], feed = createFeed();
  const first = value => seen.push(['first', value]);
  feed.subscribe(first);
  feed.subscribe(value => seen.push(['second', value]));
  assert.equal(feed.publish('a'), true);
  assert.deepEqual(seen, []);
  feed.subscribe(value => seen.push(['late', value]));
  await turn();
  assert.deepEqual(seen, [['first', 'a'], ['second', 'a']]);
  feed.publish('b');
  await turn();
  assert.deepEqual(seen.slice(2), [['first', 'b'], ['second', 'b'], ['late', 'b']]);

  const cancelled = [], cancellation = createFeed();
  const fn = value => cancelled.push(value);
  const off = cancellation.subscribe(fn);
  cancellation.publish('cancelled');
  assert.equal(off(), true);
  assert.equal(off(), false);
  await turn();
  assert.deepEqual(cancelled, []);
  const removeAgain = cancellation.subscribe(fn);
  cancellation.publish('resubscribed');
  removeAgain();
  cancellation.subscribe(fn);
  await turn();
  assert.deepEqual(cancelled, ['resubscribed']);
  const duplicateOff = cancellation.subscribe(fn);
  cancellation.publish('duplicate');
  await turn();
  assert.deepEqual(cancelled, ['resubscribed', 'duplicate']);
  assert.equal(duplicateOff(), true);

  const reentrant = [], changing = createFeed();
  let stopSecond;
  changing.subscribe(value => { reentrant.push(['first', value]); stopSecond(); });
  stopSecond = changing.subscribe(value => reentrant.push(['second', value]));
  changing.publish('remove-in-callback');
  await turn();
  assert.deepEqual(reentrant, [['first', 'remove-in-callback']]);

  const isolated = [], a = createFeed(), b = createFeed();
  a.subscribe(value => isolated.push(['a', value]));
  b.subscribe(value => isolated.push(['b', value]));
  a.publish('queued-before-close');
  a.close(); a.close();
  assert.equal(a.publish('closed'), false);
  assert.deepEqual(errorOf(() => a.subscribe(fn)), ['Error', 'closed']);
  b.publish('still-open');
  await turn();
  assert.deepEqual(isolated, [['b', 'still-open']]);

  // Native microtask error propagation is checked in an isolated real Node process.
  const child = spawnSync(process.execPath, ['-e', `
    const { createFeed } = require(process.argv[1]);
    const events = [], feed = createFeed();
    process.once('uncaughtException', error => {
      events.push([error.name, error.message]);
      setImmediate(() => console.log(JSON.stringify(events)));
    });
    feed.subscribe(() => { events.push('first'); throw new Error('subscriber failed'); });
    feed.subscribe(() => events.push('second'));
    feed.publish('x');
  `, entry], { encoding: 'utf8' });
  assert.equal(child.status, 0, child.stderr);
  const thrown = JSON.parse(child.stdout.trim());
  assert.deepEqual(thrown, ['first', ['Error', 'subscriber failed']]);
  return { exports: Object.keys(api), signatures: [makeInvoice.length, createFeed.length],
    errors, invoice, records, empty, seen, cancelled, reentrant, isolated, thrown };
}

(async () => {
  const entry = path.resolve(process.argv[2] || path.join(__dirname, '../index.cjs'));
  const current = await observe(entry);
  if (process.argv[3]) {
    assert.deepEqual(current, await observe(path.resolve(process.argv[3])));
    console.log('PASS compatibility: current and original workspace observations match');
  } else {
    console.log('PASS compatibility: public contract and native scheduler cases');
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

