"""Candidate consumer over recorded exchanges. No HTTP server or business service.
Intent persistence here is in memory; actual durable/account-isolated storage unverified.
Authentication fixture tokens are labels, not real credentials.
"""
from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path
import json
import re
from urllib.parse import urlsplit
from jsonschema import Draft202012Validator, FormatChecker

BASE = "https://orders.example.invalid/v1"
SPEC = json.loads(Path(__file__).with_name("openapi.json").read_text())
FORMAT = FormatChecker()
KEY_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")

class ContractError(ValueError):
    pass

class UnknownState(ContractError):
    pass

def validate(name, body):
    Draft202012Validator({**SPEC, "$ref": "#/components/schemas/"+name}, format_checker=FORMAT).validate(body)

def reject_duplicate(pairs):
    d={}
    for key,value in pairs:
        if key in d: raise ContractError("400 duplicate_json_member")
        d[key]=value
    return d

def strict_input(raw):
    if len(raw)>32768:raise ContractError("413 payload_too_large")
    try:
        body=json.loads(raw.decode("utf-8", errors="strict"), object_pairs_hook=reject_duplicate,
                        parse_constant=lambda _: (_ for _ in ()).throw(ContractError("400 non_finite")))
    except (UnicodeError,json.JSONDecodeError) as exc:raise ContractError("400 invalid_request") from exc
    def depth(x):
        if isinstance(x,dict):return 1+max((depth(v) for v in x.values()),default=0)
        if isinstance(x,list):return 1+max((depth(v) for v in x),default=0)
        return 0
    if depth(body)>16:raise ContractError("400 nesting_limit")
    validate("CreateOrder",body)
    skus=[v["sku"] for v in body["items"]]
    if len(set(skus))!=len(skus):raise ContractError("422 duplicate_sku")
    if sum(v["quantity"] for v in body["items"])>10000:raise ContractError("422 total_quantity")
    return body

def canonical(body):
    strict_input(json.dumps(body,allow_nan=False).encode())
    return tuple(sorted((item["sku"],int(item["quantity"])) for item in body["items"]))

@dataclass(frozen=True)
class Intent:
    tenant_context: str  # trusted account context supplied by authentication UI, not sent in body
    key: str
    canonical_items: tuple

    @classmethod
    def create(cls, tenant_context,key,body):
        if not KEY_RE.fullmatch(key):raise ContractError("400 invalid_key")
        return cls(tenant_context,key,canonical(body))

    def body(self):
        return {"items":[{"sku":sku,"quantity":qty} for sku,qty in self.canonical_items]}

    def request_url(self):return BASE+"/order-requests/"+self.key

def safe_uri(url, expected):
    if url != expected or urlsplit(url).scheme != "https":raise ContractError("untrusted_or_mismatched_resource_url")
    return url

def retry_seconds(headers,fallback=2):
    value=headers.get("Retry-After")
    if value is None:return fallback
    if not isinstance(value,str) or not value.isascii() or not value.isdigit() or value.startswith("0") or not 1<=int(value)<=3600:
        raise ContractError("invalid_retry_after")
    return int(value)

def check_state(intent,body):
    if body.get("status") not in {"accepted","processing","succeeded","failed"}:
        raise UnknownState("unknown_state_keep_intent_and_stop_writes")
    validate("OrderRequest",body)
    if body["requestKey"]!=intent.key:raise ContractError("request_key_mismatch")
    safe_uri(body["requestUrl"],intent.request_url())
    accepted=datetime.fromisoformat(body["acceptedAt"])
    updated=datetime.fromisoformat(body["updatedAt"])
    if updated<accepted:raise ContractError("time_order")
    if body["status"] in {"succeeded","failed"}:
        completed=datetime.fromisoformat(body["completedAt"])
        if completed!=updated or datetime.fromisoformat(body["retireAt"]) != completed+timedelta(days=90):
            raise ContractError("terminal_retention_or_time_mismatch")
    if body["status"]=="succeeded":check_order(intent,body["result"])
    return body["status"]

def check_order(intent,body):
    validate("Order",body)
    if body["requestKey"]!=intent.key or canonical({"items":[{"sku":i["sku"],"quantity":i["quantity"]} for i in body["items"]]})!=intent.canonical_items:
        raise ContractError("order_identity_or_items_mismatch")
    safe_uri(body["orderUrl"],BASE+"/orders/"+body["orderId"])
    datetime.fromisoformat(body["createdAt"])

ERRORS={
  "invalid_request":(400,False,"none","fix_input"),"invalid_items":(422,False,"none","fix_input"),
  "payload_too_large":(413,False,"none","fix_input"),"unsupported_media_type":(415,False,"none","fix_input"),
  "not_acceptable":(406,False,"none","fix_input"),"unauthenticated":(401,False,"none","authenticate"),
  "forbidden":(403,False,"none","request_permission"),"not_found":(404,False,"none","stop"),
  "idempotency_conflict":(409,False,"existing_request","poll_existing"),
  "tenant_capacity":(409,False,"none","stop"),"request_retired":(410,False,"existing_request","inspect_retired"),
  "rate_limited":(429,True,"none","wait_then_retry"),"admission_limited":(429,True,"none","wait_then_retry"),
  "temporarily_unavailable":(503,True,"unknown","retry_same_key_after_lookup"),
  "internal_error":(500,True,"unknown","retry_same_key_after_lookup")}

def consume(intent,method,url,response):
    """Return a concrete next action. Callers apply jitter/budgets via RetryBudget.
    404→same-key replay applies ONLY to the known request URL, never an order URL.
    """
    if response.get("transportError"):
        return {"action":"lookup","url":intent.request_url(),"keepKey":intent.key}
    status=response["status"];headers=response["headers"];body=response["body"]
    if len(json.dumps(body,ensure_ascii=False).encode("utf-8"))>65536:raise ContractError("response_size_limit")
    if headers.get("Cache-Control")!="no-store":raise ContractError("cache_policy")
    if not re.fullmatch(r"req_[a-z0-9]{8,64}",headers.get("X-Request-Id","")):raise ContractError("request_correlation")
    if 200<=status<300:
        if headers.get("Content-Type")!="application/json":raise ContractError("success_media")
        if url.startswith(BASE+"/orders/"):
            if method!="GET" or status!=200:raise ContractError("order_method_status")
            check_order(intent,body);safe_uri(body["orderUrl"],url)
            return {"action":"display_order","orderId":body["orderId"]}
        expected = BASE+"/order-requests" if method=="POST" else intent.request_url()
        safe_uri(url,expected)
        state=check_state(intent,body)
        if method=="POST":
            safe_uri(headers.get("Location"),intent.request_url())
            if status != (202 if state in {"accepted","processing"} else 200):raise ContractError("post_status_state")
        elif status!=200:raise ContractError("get_status")
        if state in {"accepted","processing"}:
            return {"action":"poll","url":intent.request_url(),"waitSeconds":retry_seconds(headers),"needsAttention":body.get("needsAttention",False)}
        if "Retry-After" in headers:raise ContractError("terminal_retry_after")
        if state=="failed":return {"action":"show_failure","code":body["error"]["code"],"doNotReplay":True}
        return {"action":"read_order","url":body["result"]["orderUrl"],"orderId":body["result"]["orderId"]}
    if headers.get("Content-Type")!="application/problem+json":raise ContractError("problem_media")
    validate("Problem",body)
    if body["status"]!=status or body["requestId"]!=headers["X-Request-Id"]:raise ContractError("problem_status_or_correlation")
    code=body["code"]
    if code not in ERRORS:raise ContractError("unknown_error_stop_writes")
    if (status,body["retryable"],body["effect"],body["nextAction"])!=ERRORS[code]:raise ContractError("problem_semantics")
    if body["type"]!=BASE.removesuffix("/v1")+"/problems/"+code:raise ContractError("problem_type")
    if status==401:
        if not headers.get("WWW-Authenticate","").startswith("Bearer "):raise ContractError("missing_bearer_challenge")
        return {"action":"reauthenticate_then_lookup_same_tenant","keepKey":intent.key}
    if code=="idempotency_conflict":
        safe_uri(body.get("requestUrl"),intent.request_url())
        return {"action":"show_conflict_and_poll_original","url":intent.request_url(),"doNotCreateNewKey":True}
    if code=="request_retired":return {"action":"show_retired","doNotCreateNewKey":True}
    if code=="not_found" and method=="GET" and url==intent.request_url():
        return {"action":"replay_same_intent","key":intent.key,"body":intent.body()}
    if status in {500,503}:return {"action":"lookup","url":intent.request_url(),"keepKey":intent.key,"waitSeconds":retry_seconds(headers)}
    if status==429:return {"action":"wait_then_lookup" if method=="POST" else "wait_then_get","url":intent.request_url() if method=="POST" else url,"waitSeconds":retry_seconds(headers)}
    return {"action":"stop_and_"+body["nextAction"],"doNotCreateNewKey":True}

@dataclass
class RetryBudget:
    elapsed:float=0
    polls:int=0
    replays:int=0
    def next(self,action, jitter_fraction=0.0):
        if not 0<=jitter_fraction<=0.2:raise ContractError("jitter_range")
        wait=action.get("waitSeconds",0)*(1+jitter_fraction)
        is_poll=action["action"] in {"poll","lookup","wait_then_lookup","wait_then_get"}
        is_replay=action["action"]=="replay_same_intent"
        if self.elapsed+wait>=900 or (is_poll and self.polls>=180) or (is_replay and self.replays>=3):
            return {"action":"resume_later","keepIntent":True}
        self.elapsed+=wait;self.polls+=int(is_poll);self.replays+=int(is_replay)
        return action
    def record_http_elapsed(self,seconds):
        if seconds<0:raise ContractError("negative_elapsed")
        self.elapsed+=seconds

def run_examples():
    scenarios=json.loads(Path(__file__).with_name("examples.json").read_text())
    for scenario in scenarios:
        intent=Intent.create(scenario["tenantContext"],scenario["key"],scenario["originalBody"])
        for exchange in scenario["exchanges"]:
            actual=consume(intent,exchange["request"]["method"],exchange["request"]["url"],exchange["response"])
            if actual!=exchange["expected"]:
                raise AssertionError((scenario["name"],actual,exchange["expected"]))
        print("PASS",scenario["name"])

if __name__=="__main__":run_examples()

