          "createdAt": {
            "type": "string",
            "format": "date-time",
            "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z(?![\\s\\S])"
          }
        },
        "additionalProperties": true
      },
      "BusinessFailure": {
        "type": "object",
        "required": [
          "code",
          "retryable",
          "detail"
